actions.script:
const pref = (key) => { const value = ec.user.getPreference(key); return value == null ? '' : String(value).trim() }
const time = (text, fallback) => /^\d{2}:\d{2}$/.test(text) ? text : fallback
const view = pref('CALENDAR_DEFAULT_VIEW')
const weekStart = pref('CALENDAR_WEEK_START')
const duration = Number(pref('CALENDAR_DEFAULT_DURATION'))
const reminderText = ec.user.getPreference('CALENDAR_DEFAULT_REMINDER')
const reminder = reminderText == null ? '10' : String(reminderText).trim()
const days = pref('CALENDAR_WORK_DAYS').split(',').map((day) => day.trim()).filter((day) => /^[0-6]$/.test(day))
defaults = {view: ['day', 'workweek', 'week', 'month', 'agenda'].includes(view) ? view : 'week',
    weekStart: ['0', '1', '6'].includes(weekStart) ? Number(weekStart) : 0,
    workStart: time(pref('CALENDAR_WORK_START'), '09:00'), workEnd: time(pref('CALENDAR_WORK_END'), '17:00'),
    workDays: days.length ? days.map(Number) : [1, 2, 3, 4, 5],
    defaultDuration: [15, 30, 45, 60, 90, 120].includes(duration) ? duration : 60,
    defaultReminder: /^\d+$/.test(reminder) && Number(reminder) <= 43200 ? reminder : '',
    showDeclined: pref('CALENDAR_SHOW_DECLINED') === 'Y', showWeekNumbers: pref('CALENDAR_SHOW_WEEK_NUMBERS') === 'Y',
    showTasks: pref('CALENDAR_SHOW_TASKS') === 'Y',
    hiddenCalendarIds: pref('CALENDAR_HIDDEN').split(',').map((id) => id.trim()).filter((id) => id)}
if (defaults.workEnd <= defaults.workStart) { defaults.workStart = '09:00'; defaults.workEnd = '17:00' }

const L = (text) => ec.l10n.localize(text)
const yes = (value) => value === 'Y' || value === 'true' || value === true || (Array.isArray(value) && value.includes('Y'))
if (view != null) {
    if (!['day', 'workweek', 'week', 'month', 'agenda'].includes(String(view))) { ec.message.addError(L('Pick a view: day, work week, week, month or agenda')); return }
    ec.user.setPreference('CALENDAR_DEFAULT_VIEW', String(view))
}
if (weekStart != null) {
    if (!['0', '1', '6'].includes(String(weekStart))) { ec.message.addError(L('A week starts on Sunday, Monday or Saturday')); return }
    ec.user.setPreference('CALENDAR_WEEK_START', String(weekStart))
}
const time = (value) => { const text = String(value || '').trim(); return /^\d{1,2}:\d{2}$/.test(text) ? text.padStart(5, '0') : null }
if (workStart != null || workEnd != null) {
    const start = time(workStart) || '09:00'
    const end = time(workEnd) || '17:00'
    if (end <= start) { ec.message.addError(L('Working hours end after they start')); return }
    ec.user.setPreference('CALENDAR_WORK_START', start)
    ec.user.setPreference('CALENDAR_WORK_END', end)
}
if (workDays != null) {
    const list = (Array.isArray(workDays) ? workDays : String(workDays).split(',')).map((day) => String(day).trim()).filter((day) => /^[0-6]$/.test(day))
    if (!list.length) { ec.message.addError(L('Pick at least one working day')); return }
    ec.user.setPreference('CALENDAR_WORK_DAYS', Array.from(new Set(list)).sort().join(','))
}
if (defaultDuration != null) {
    if (![15, 30, 45, 60, 90, 120].includes(Number(defaultDuration))) { ec.message.addError(L('A default length is 15 minutes to 2 hours')); return }
    ec.user.setPreference('CALENDAR_DEFAULT_DURATION', String(Number(defaultDuration)))
}
if (defaultReminder != null) {
    const text = String(defaultReminder).trim()
    if (text && !(/^\d+$/.test(text) && Number(text) <= 43200)) { ec.message.addError(L('A reminder is up to 30 days before')); return }
    ec.user.setPreference('CALENDAR_DEFAULT_REMINDER', text)
}
if (showDeclined != null) ec.user.setPreference('CALENDAR_SHOW_DECLINED', yes(showDeclined) ? 'Y' : 'N')
if (showWeekNumbers != null) ec.user.setPreference('CALENDAR_SHOW_WEEK_NUMBERS', yes(showWeekNumbers) ? 'Y' : 'N')
// the working hours as Mantle reads them for free/busy and Find a time: a weekly WetAvailable of the user's
if (workStart != null || workEnd != null || workDays != null) {
    ec.message.pushErrors()
    try {
        ec.service.sync().name('ironstone.commons.CalendarServices.store#WorkingHours').call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    } catch (err) {
        ec.logger.warn(`The working hours of ${ec.user.username} were not stored for free/busy: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
if (defaultCalendarId) {
    const access = ec.service.sync().name('mantle.work.CalendarServices.check#CalendarAccess').parameters({calendarId: defaultCalendarId}).call()
    if (ec.message.hasError()) return
    if (!access?.isOwner || access.calendar?.calendarKindEnumId !== 'CalkPersonal') {
        ec.message.addError(L('Only one of your own personal calendars can be your default')); return }
    if (access.calendar.isDefault !== 'Y') ec.service.sync().name('mantle.work.CalendarServices.update#Calendar')
            .parameters({calendarId: defaultCalendarId, isDefault: 'Y'}).call()
    if (ec.message.hasError()) return
}
message = L('Calendar settings saved')

const own = !partyId || partyId === ec.user.userAccount?.partyId
if (own && !ec.user.userAccount?.partyId) return
let parameters
if (own) {
    const defaults = ec.service.sync().name('ironstone.commons.CalendarServices.get#CalendarDefaults').call()?.defaults || {}
    parameters = {workDays: defaults.workDays || [1, 2, 3, 4, 5], workStart: defaults.workStart, workEnd: defaults.workEnd,
        timeZone: ec.user.timeZone || null, sourceReferenceId: 'BossWorkingHours'}
} else {
    parameters = {partyId: partyId, workDays: workDays, workStart: workStart, workEnd: workEnd, timeZone: timeZone || null,
        fromDate: fromDate || null}
}
const out = ec.service.sync().name('mantle.work.CalendarServices.store#WorkingHours').parameters(parameters).call()
if (ec.message.hasError()) return
workEffortId = out?.workEffortId || null
calendarId = out?.calendarId || null

if (hiddenCalendarIds != null) {
    const list = (Array.isArray(hiddenCalendarIds) ? hiddenCalendarIds : String(hiddenCalendarIds).split(','))
            .map((id) => String(id).trim()).filter((id) => id && /^[A-Za-z0-9_.:-]+$/.test(id))
    ec.user.setPreference('CALENDAR_HIDDEN', Array.from(new Set(list)).slice(0, 200).join(','))
}
if (showTasks != null) ec.user.setPreference('CALENDAR_SHOW_TASKS', showTasks === 'Y' || showTasks === 'true' ? 'Y' : 'N')
if (showDeclined != null) ec.user.setPreference('CALENDAR_SHOW_DECLINED', showDeclined === 'Y' || showDeclined === 'true' ? 'Y' : 'N')

const L = (text) => ec.l10n.localize(text)
calendarList = []
defaultCalendarId = null
roomOptions = []
failedSources = []
const attempt = (name, run) => {
    ec.message.pushErrors()
    try { run(); if (ec.message.hasError()) throw new Error(ec.message.getErrorsString()) }
    catch (err) { failedSources.push(name); ec.logger.error(`Calendar ${name} for ${ec.user.username} not read: ${err && err.message ? err.message : err}`) }
    finally { ec.message.clearErrors(); ec.message.popErrors() }
}
defaults = ec.service.sync().name('ironstone.commons.CalendarServices.get#CalendarDefaults').call()?.defaults || {}
timeZone = ec.user.timeZone || ''
const nowMs = Number(String(ec.user.nowTimestamp))
todayText = ec.l10n.format(String(nowMs), 'yyyy-MM-dd')
nowText = ec.l10n.format(String(nowMs), 'yyyy-MM-dd HH:mm')
const partyId = ec.user.userAccount?.partyId || null
me = {partyId: partyId, name: ec.user.userAccount?.userFullName || ec.user.username, userId: ec.user.userId}
const hidden = new Set(defaults.hiddenCalendarIds || [])
attempt('calendars', () => {
    const out = ec.service.sync().name('mantle.work.CalendarServices.get#UserCalendars').call()
    if (ec.message.hasError()) return
    defaultCalendarId = out?.defaultCalendarId || null
    for (const calendar of Array.from(out?.calendarList || [])) {
        const subscription = calendar.subscription
        let warning = null
        if (subscription && subscription.lastFetchStatus === 'error') warning = L('Last fetch failed') + (subscription.lastFetchError ? ': ' + String(subscription.lastFetchError).substring(0, 200) : '')
        else if (subscription && !subscription.lastFetchDate) warning = L('Not fetched yet')
        calendarList.push(Object.assign({}, calendar, {shown: !hidden.has(calendar.calendarId),
            canAdd: ['CalpEdit', 'CalpManage'].includes(calendar.permissionEnumId) && calendar.calendarKindEnumId !== 'CalkSubscription',
            freeBusyOnly: calendar.permissionEnumId === 'CalpFreeBusy', warning: warning,
            lastFetchText: subscription?.lastFetchDate ? ec.l10n.format(subscription.lastFetchDate, 'MMM d, h:mm a') : null}))
    }
})
attempt('rooms', () => {
    for (const room of ec.entity.find('mantle.facility.Facility').condition('facilityTypeEnumId', 'FcTpRoom').condition('bookable', 'Y')
            .condition('closedDate', 'is-null', null).orderBy('facilityName').limit(200).list())
        roomOptions.push({value: room.facilityId, label: room.facilityName || room.facilityId})
})

eventList = []
skippedCalendarIdList = []
failedSources = []
const cf = ec.entity.conditionFactory
const textList = (value) => value == null ? [] : (Array.isArray(value) ? value : String(value).split(',')).map((id) => String(id).trim()).filter((id) => id)
const dayOk = (text) => /^\d{4}-\d{2}-\d{2}$/.test(String(text || ''))
if (!dayOk(start) || !dayOk(end) || String(end) < String(start)) { ec.message.addError(ec.l10n.localize('The range is two days, yyyy-MM-dd')); return }
const partyId = ec.user.userAccount?.partyId || null
const shownIds = textList(calendarIds)
const hiddenIds = new Set(textList(hiddenCalendarIds))
const wall = (text) => text ? String(text).replace('T', ' ').substring(0, 16) : null
const attempt = (name, run) => {
    ec.message.pushErrors()
    try { run(); if (ec.message.hasError()) throw new Error(ec.message.getErrorsString()) }
    catch (err) { failedSources.push(name); ec.logger.error(`Calendar ${name} for ${ec.user.username} not read: ${err && err.message ? err.message : err}`) }
    finally { ec.message.clearErrors(); ec.message.popErrors() }
}
let events = []
attempt('events', () => {
    const out = ec.service.sync().name('mantle.work.EventServices.get#FullCalendarData').parameters({start: start, end: end,
        calendarIdList: shownIds, showDeclined: !!showDeclined, excludeCancelled: true,
        titleGString: '${workEffort.workEffortName || "(no title)"}'}).call()
    if (ec.message.hasError()) return
    events = Array.from(out?.eventList || [])
    skippedCalendarIdList = Array.from(out?.skippedCalendarIdList || [])
})
if (events.length) attempt('event details', () => {
    const ids = Array.from(new Set(events.map((event) => event.workEffortId)))
    // the calendars each event is in, for the permission and for the calendars the user turned off
    const calendarsOf = new Map()
    // the calendars that make their editors the event's: not one it was only put in to be seen (viewOnly)
    const editCalendarsOf = new Map()
    for (const link of ec.entity.find('mantle.work.calendar.CalendarWorkEffort').condition(cf.makeCondition('workEffortId', 'in', ids)).list()) {
        if (!calendarsOf.has(link.workEffortId)) { calendarsOf.set(link.workEffortId, []); editCalendarsOf.set(link.workEffortId, []) }
        calendarsOf.get(link.workEffortId).push(link.calendarId)
        if (link.viewOnly !== 'Y') editCalendarsOf.get(link.workEffortId).push(link.calendarId)
    }
    // the events an application keeps are changed there, never on the grid
    const managed = ec.service.sync().name('mantle.work.EventServices.get#ManagedEvents').parameters({workEffortIdList: ids}).call()?.managedMap || {}
    const permissionIds = Array.from(new Set([].concat(...Array.from(calendarsOf.values()))))
    const permissions = permissionIds.length ? (ec.service.sync().name('mantle.work.CalendarServices.check#CalendarAccess')
            .parameters({calendarIdList: permissionIds}).call()?.permissionMap || {}) : {}
    const kinds = new Map()
    if (permissionIds.length) for (const calendar of ec.entity.find('mantle.work.calendar.Calendar').condition(cf.makeCondition('calendarId', 'in', permissionIds))
            .selectField('calendarId,calendarKindEnumId').list()) kinds.set(calendar.calendarId, calendar.calendarKindEnumId)
    const others = new Map()
    for (const party of ec.entity.find('mantle.work.effort.WorkEffortParty').condition(cf.makeCondition('workEffortId', 'in', ids))
            .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).selectField('workEffortId,partyId').list())
        if (party.partyId !== partyId) others.set(party.workEffortId, (others.get(party.workEffortId) || 0) + 1)
    for (const event of events) {
        const calendars = calendarsOf.get(event.workEffortId) || []
        // in the user's calendars only where they are turned off: not shown
        if (calendars.length && !calendars.some((id) => shownIds.includes(id)) && calendars.some((id) => hiddenIds.has(id))
                && !(event.partyStatusId && ['WeptOffered', 'WeptTentative'].includes(event.partyStatusId) && event.ownerPartyId !== partyId)) continue
        const isOrganizer = !!partyId && event.ownerPartyId === partyId
        const canEdit = !event.freeBusyOnly && !managed[event.workEffortId] && (isOrganizer || (editCalendarsOf.get(event.workEffortId) || [])
                .some((id) => ['CalpEdit', 'CalpManage'].includes(permissions[id]) && kinds.get(id) !== 'CalkSubscription'))
        const instanceStart = event.instanceStart ? (event.allDay ? String(event.instanceStart).substring(0, 10) : wall(event.instanceStart)) : null
        eventList.push({kind: 'event', key: event.workEffortId + '|' + (instanceStart || '') + '|' + event.startMillis, workEffortId: event.workEffortId,
            title: event.title, start: event.allDay ? event.start : wall(event.start), end: event.allDay ? event.end : wall(event.end), allDay: !!event.allDay,
            color: event.color || null, calendarId: event.calendarId || null, statusId: event.statusId || null, partyStatusId: event.partyStatusId || null,
            recurring: !!event.recurring, recurringEventId: event.recurringEventId || null, instanceStart: instanceStart,
            freeBusyOnly: !!event.freeBusyOnly, location: event.freeBusyOnly ? null : (event.location || null), canEdit: canEdit,
            isOrganizer: isOrganizer, hasAttendees: (others.get(event.workEffortId) || 0) > 0,
            url: event.freeBusyOnly ? null : '/qapps/Commons/Calendar/EventDetail?workEffortId=' + encodeURIComponent(event.workEffortId)
                + (instanceStart && event.recurringEventId === event.workEffortId ? '&instanceStart=' + encodeURIComponent(instanceStart) : '')})
    }
})
if (showTasks && partyId) attempt('tasks', () => {
    const out = ec.service.sync().name('mantle.work.TaskServices.get#FullCalendarData').parameters({partyId: partyId, start: start, end: end,
        titleGString: '${workEffort.workEffortName || "(no name)"}'}).call()
    if (ec.message.hasError()) return
    const tasks = Array.from(out?.eventList || [])
    const ids = Array.from(new Set(tasks.map((task) => task.id)))
    const statuses = new Map()
    if (ids.length) for (const row of ec.entity.find('mantle.work.effort.WorkEffort').condition(cf.makeCondition('workEffortId', 'in', ids))
            .selectField('workEffortId,statusId,estimatedCompletionDate').list()) statuses.set(row.workEffortId, row)
    const seen = new Set()
    for (const task of tasks) {
        if (seen.has(task.id)) continue
        seen.add(task.id)
        const row = statuses.get(task.id)
        if (row?.statusId === 'WeCancelled') continue
        // a task is at its due time, half an hour long
        const due = row?.estimatedCompletionDate != null ? ec.l10n.format(row.estimatedCompletionDate, 'yyyy-MM-dd HH:mm') : wall(task.end || task.start)
        if (!due) continue
        const dueMs = Number(String(ec.l10n.parseTimestamp(due + ':00.000', 'yyyy-MM-dd HH:mm:ss.SSS')))
        const startText = ec.l10n.format(String(dueMs - 1800000), 'yyyy-MM-dd HH:mm')
        eventList.push({kind: 'task', key: 'task|' + task.id, workEffortId: task.id, title: task.title, start: due.substring(0, 10) === startText.substring(0, 10) ? startText : due,
            end: due, allDay: false, color: null, statusId: row?.statusId || null, done: ['WeComplete', 'WeClosed'].includes(row?.statusId),
            canEdit: false, url: '/qapps/Commons/Tasks/TaskDetail?workEffortId=' + encodeURIComponent(task.id)})
    }
})

found = false; visible = false; canEdit = false; isOrganizer = false; isAttendee = false; workEffort = null; managedBy = null
const notAvailable = () => ec.resource.expand('Event ${workEffortId} is not available', '', {workEffortId: workEffortId})
const row = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
// a production run (WepProductionRun, a WetEvent) is no event: Manufacturing's services change and copy it, so
// EventDetail, its edits and duplicate#Event refuse it (impl-manufacturing F39)
if (row == null || row.workEffortTypeEnumId !== 'WetEvent' || row.purposeEnumId === 'WepProductionRun') {
    if (need !== 'check') ec.message.addError(notAvailable())
    return
}
found = true
// permission check: an answer without an error, whatever the user may do
const access = ec.service.sync().name('mantle.work.EventServices.check#EventAccess').parameters({workEffortId: workEffortId, permission: 'check'}).call()
if (ec.message.hasError()) return
canEdit = !!access?.canEdit
isOrganizer = !!access?.isOrganizer
isAttendee = !!access?.isAttendee
managedBy = access?.managedBy || null
visible = !!access?.canView
if (!visible) {
    const info = ec.service.sync().name('mantle.party.CommunicationServices.get#RecordLinkInfo').parameters({
        recordEntityName: 'mantle.work.effort.WorkEffort', recordId: workEffortId, checkOnly: true}).call()
    if (ec.message.hasError()) return
    visible = info?.recordVisible === true
    if (!visible) ec.logger.info(`Event ${workEffortId} is not visible to user ${ec.user.userId}: ${info?.notVisibleReason || 'not on it'}`)
}
if (!visible) { if (need !== 'check') ec.message.addError(notAvailable()); return }
workEffort = row.getMap()
if (need === 'edit' && !canEdit && managedBy) ec.message.addError(ec.resource.expand('${name} is changed on ${managedBy}', '',
        {name: row.workEffortName || workEffortId, managedBy: managedBy}))
else if (need === 'edit' && !canEdit) ec.message.addError(ec.resource.expand('Only the organizer of ${name} or an editor of its calendar may change it', '',
        {name: row.workEffortName || workEffortId}))

const L = (text) => ec.l10n.localize(text)
const cf = ec.entity.conditionFactory
const pattern = 'yyyy-MM-dd HH:mm:ss.SSS'
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const fmt = (millis, format) => ec.l10n.format(String(millis), format)
const dayTextOf = (value) => {
    if (value == null || value === '') return null
    const text = String(value)
    if (/^\d{4}-\d{2}-\d{2}/.test(text)) return text.substring(0, 10)
    return new Date(toMillis(value)).toISOString().substring(0, 10)
}
const addDays = (text, days) => { const [y, m, d] = text.split('-').map(Number); return new Date(Date.UTC(y, m - 1, d + days)).toISOString().substring(0, 10) }
const dayLabel = (text) => ec.l10n.format(ec.l10n.parseDate(text, 'yyyy-MM-dd'), 'EEE, MMM d, yyyy')
const nameOf = (detail) => detail ? (detail.organizationName || [detail.firstName, detail.lastName].filter((part) => part).join(' ') || detail.partyId) : null
const statusInfo = {WeptAssigned: ['Accepted', 'positive'], WeptTentative: ['Maybe', 'warning'], WeptDeclined: ['Declined', 'negative'],
    WeptOffered: ['Not answered', 'grey-7'], WeptUnassigned: ['Removed', 'grey-7']}
const bookingInfo = {WefRequested: ['Pending approval', 'warning'], WefAssigned: ['Booked', 'positive'], WefRequestDenied: ['Request denied', 'negative'],
    WeaaRequested: ['Pending approval', 'warning'], WeaaAssigned: ['Booked', 'positive'], WeaaRequestDenied: ['Request denied', 'negative']}
const row = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (row == null) { event = null; return }
const myPartyId = ec.user.userAccount?.partyId || null
// the series of an instance changed on its own
const instanceLink = ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('toWorkEffortId', workEffortId)
        .condition('workEffortAssocTypeEnumId', 'WeatRecurrenceInstance').one()
const seriesId = instanceLink ? instanceLink.workEffortId : workEffortId
const recurrence = ec.entity.find('mantle.work.effort.WorkEffortRecurrence').condition('workEffortId', seriesId).one()
const isRecurring = !!(recurrence?.rrule || instanceLink)
// when: the instance asked (a generated one has the series' fields), else the event's own dates
const startMs = toMillis(row.actualStartDate || row.estimatedStartDate)
let endMs = toMillis(row.actualCompletionDate || row.estimatedCompletionDate)
if (startMs != null && endMs == null) {
    const span = ec.service.sync().name('mantle.work.WorkEffortServices.get#WorkEffortStartEnd').parameters({workEffortId: workEffortId}).call()
    endMs = toMillis(span?.endDate)
}
const allDay = startMs == null && row.allDayStart != null
let startText = null, endText = null, whenText = L('Time to be set')
let instanceText = instanceStart ? String(instanceStart).replace('T', ' ') : null
if (allDay) {
    let first = dayTextOf(row.allDayStart)
    let last = dayTextOf(row.allDayEnd) || first
    if (last < first) last = first
    if (instanceText && !instanceLink && /^\d{4}-\d{2}-\d{2}$/.test(instanceText.substring(0, 10))) {
        const span = Math.round((Date.UTC(...last.split('-').map((part, index) => index === 1 ? Number(part) - 1 : Number(part)))
            - Date.UTC(...first.split('-').map((part, index) => index === 1 ? Number(part) - 1 : Number(part)))) / 86400000)
        first = instanceText.substring(0, 10)
        last = addDays(first, span)
    }
    startText = first
    endText = addDays(last, 1)
    whenText = dayLabel(first) + (last > first ? ' – ' + dayLabel(last) : '') + ' · ' + L('All day')
} else if (startMs != null) {
    let shownStart = startMs
    if (instanceText && !instanceLink && /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}/.test(instanceText)) {
        const parsed = toMillis(ec.l10n.parseTimestamp(instanceText.substring(0, 16) + ':00.000', pattern))
        if (parsed != null) shownStart = parsed
    }
    const shownEnd = endMs != null ? shownStart + (endMs - startMs) : null
    startText = fmt(shownStart, 'yyyy-MM-dd HH:mm')
    endText = shownEnd != null ? fmt(shownEnd, 'yyyy-MM-dd HH:mm') : null
    whenText = fmt(shownStart, 'EEE, MMM d, yyyy · h:mm a')
    if (shownEnd != null) whenText += ' – ' + (fmt(shownStart, 'yyyy-MM-dd') === fmt(shownEnd, 'yyyy-MM-dd') ? fmt(shownEnd, 'h:mm a') : fmt(shownEnd, 'EEE, MMM d, h:mm a'))
}
// a series shown without an instance: its first
if (recurrence?.rrule && !instanceLink && !instanceText && startText) whenText = L('From') + ' ' + whenText
const recurrenceText = recurrence?.rrule ? (ec.service.sync().name('ironstone.commons.CalendarServices.describe#RRule').parameters({rrule: recurrence.rrule,
        startText: allDay ? startText : (startMs != null ? fmt(startMs, 'yyyy-MM-dd HH:mm') : null)}).call()?.text || null)
        : (instanceLink ? L('Changed from its series') : null)
// the join link: the event's link, else a web address in the location or the description
const urlIn = (text) => { const match = text ? /https?:\/\/[^\s<>"')]+/i.exec(String(text)) : null; return match ? match[0] : null }
const joinUrl = row.infoUrl && /^https?:\/\//i.test(String(row.infoUrl)) ? String(row.infoUrl) : (urlIn(row.location) || urlIn(row.description))
// people
