const nameOfParty = (partyId) => {
    const detail = partyId ? ec.entity.find('mantle.party.PartyDetail').condition('partyId', partyId).one() : null
    return detail ? (detail.organizationName || [detail.firstName, detail.lastName].filter((part) => part).join(' ') || partyId) : partyId
}
for (const calendar of Array.from(out?.calendarList || [])) {
    const entry = Object.assign({}, calendar, {kindText: L(kindText[calendar.calendarKindEnumId] || calendar.calendarKindEnumId || ''),
        permissionText: L(permissionText[calendar.permissionEnumId] || ''), canManage: calendar.permissionEnumId === 'CalpManage',
        sharedWithText: '', colorText: calendar.color || ''})
    if (calendar.subscription) {
        const sub = calendar.subscription
        entry.url = sub.url
        entry.refreshMinutes = sub.refreshMinutes
        entry.lastFetchText = sub.lastFetchDate ? ec.l10n.format(sub.lastFetchDate, 'MMM d, yyyy h:mm a') : L('Never')
        entry.fetchStatus = sub.lastFetchStatus || (sub.lastFetchDate ? 'ok' : 'new')
        entry.fetchStatusText = sub.lastFetchStatus === 'error' ? L('Failed') : (sub.lastFetchDate ? L('OK') : L('Not fetched yet'))
        entry.fetchError = sub.lastFetchError || null
    }
    if (entry.canManage) {
        const names = []
        for (const share of ec.entity.find('mantle.work.calendar.CalendarShare').condition('calendarId', calendar.calendarId)
                .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).list()) {
            if (share.publishToken && !share.userId && !share.userGroupId && !share.partyId) continue
            let who = share.userId || share.userGroupId || share.partyId
            let whoKind = 'party'
            if (share.userId) {
                whoKind = 'user'
                const account = ec.entity.find('moqui.security.UserAccount').condition('userId', share.userId).disableAuthz().one()
                who = account ? (account.userFullName || account.username) : share.userId
            } else if (share.userGroupId) {
                whoKind = 'group'
                const group = ec.entity.find('moqui.security.UserGroup').condition('userGroupId', share.userGroupId).one()
                who = group ? (group.description || share.userGroupId) : share.userGroupId
            } else who = nameOfParty(share.partyId)
            names.push(who)
            shareList.push({calendarShareId: share.calendarShareId, calendarId: calendar.calendarId, calendarName: calendar.calendarName,
                who: who, whoKind: whoKind, permissionEnumId: share.permissionEnumId, permissionText: L(permissionText[share.permissionEnumId] || share.permissionEnumId),
                sinceText: share.fromDate ? ec.l10n.format(share.fromDate, 'MMM d, yyyy') : ''})
        }
        entry.sharedWithText = names.join(', ')
    }
    if (calendar.group === 'mine') mineList.push(entry)
    else if (calendar.group === 'subscription') subscriptionList.push(entry)
    else sharedList.push(entry)
}

const L = (text) => ec.l10n.localize(text)
const access = ec.service.sync().name('mantle.work.CalendarServices.check#CalendarAccess').parameters({calendarId: calendarId, permissionEnumId: 'CalpManage'}).call()
if (ec.message.hasError()) return
if (access?.calendar?.calendarKindEnumId !== 'CalkSubscription') { ec.message.addError(L('Only a subscription is fetched')); return }
const out = ec.service.sync().name('mantle.work.CalendarServices.fetch#CalendarSubscriptions').parameters({calendarId: calendarId, force: true}).call()
if (ec.message.hasError()) return
const subscription = ec.entity.find('mantle.work.calendar.CalendarSubscription').condition('calendarId', calendarId).one()
if (!out?.toolAvailable) { status = 'error'; message = L('Calendar feeds cannot be read: the iCalendar tool is not available'); return }
status = subscription?.lastFetchStatus || 'error'
message = status === 'ok' ? ec.resource.expand('${name} fetched', '', {name: access.calendar.calendarName})
        : ec.resource.expand('${name} was not fetched: ${error}', '', {name: access.calendar.calendarName, error: subscription?.lastFetchError || L('no answer')})

const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
valid = false
routeContext = null
const tokenText = token == null ? '' : String(token).trim()
if (!/^[A-Za-z0-9_-]{16,128}$/.test(tokenText)) return
const share = ec.entity.find('mantle.work.calendar.CalendarShare').condition('publishToken', tokenText).disableAuthz().one()
if (share == null || share.userId || share.userGroupId || share.partyId) return
valid = true
const now = toMillis(ec.user.nowTimestamp)
const from = toMillis(share.fromDate)
const thru = toMillis(share.thruDate)
if ((from != null && from > now) || (thru != null && thru <= now)) { routeContext = {expired: true}; return }
const calendar = ec.entity.find('mantle.work.calendar.Calendar').condition('calendarId', share.calendarId).disableAuthz().one()
if (calendar == null) { routeContext = {expired: true}; return }
routeContext = {expired: false, calendarName: calendar.calendarName ?? null, color: calendar.color ?? null,
    needsPassword: !!share.passwordHash}

const L = (text) => ec.l10n.localize(text)
needsPassword = false
calendarName = null
color = null
eventList = []
const tokenText = token == null ? '' : String(token).trim()
if (!/^[A-Za-z0-9_-]{16,128}$/.test(tokenText)) { ec.message.addError(L('This calendar link is not valid')); return }
const share = ec.entity.find('mantle.work.calendar.CalendarShare').condition('publishToken', tokenText)
        .condition(ec.entity.conditionFactory.makeConditionDate('fromDate', 'thruDate', null)).disableAuthz().one()
if (share == null || share.userId || share.userGroupId || share.partyId) {
    ec.message.addError(L('This calendar link is not valid')); return }
const calendar = ec.entity.find('mantle.work.calendar.Calendar').condition('calendarId', share.calendarId).disableAuthz().one()
calendarName = calendar?.calendarName ?? null
color = calendar?.color ?? null
if (share.passwordHash) {
    const given = password == null ? '' : String(password)
    if (!given) { needsPassword = true; return }
    if (!ec.user.passwordsMatch(given, share.passwordHash)) { ec.message.addError(L('The password is not right')); return }
}
if (!start || !end) { ec.message.addError(L('Choose the dates to show')); return }
const out = ec.service.sync().name('mantle.work.CalendarServices.get#PublishedCalendarEvents').parameters({publishToken: tokenText,
    password: password || null, start: start, end: end}).call()
if (ec.message.hasError()) return
eventList = out?.eventList || []
